// Copy of private WIP "Snake in mesh - study2" https://shadertoy.com/view/lfycWD
// v2 of https://shadertoy.com/view/XcccWf
// mesh from https://shadertoy.com/view/MfccD2

float line(vec2 a,vec2 b) { 
   b -= a;
   return length( a + b * clamp( -dot(a, b) / dot(b, b), 0., 1.)); 
}

#define P(x,y)    ( D = vec2(x+k%2,y+k/2) - 1. , .5 + D - fract(p) + T( p + D ).xy )
                                                // = floor(p)+offs -p +.5 + rand

void mainImage( out vec4 O, vec2 u )
{
    vec2  h0,h1,h2,h3, D,
          p = scale* u / R.y;
    float d = 9.;
#if 0                       
    for( int k; k < 4; k++ )                    // --- draw mesh
        h0 = P(0,0), 
        h1 = P(1,0),
        h2 = P(0,1),         
        h3 = P(1,1),     
        d = min( min( line(h0,h1),
                      line(h0,h2) ),
              // min( (int(T(p).z)& 1 << ( k%2*2 + k/2*2*3) ) > 0 // why wrong ?
                 min( length(h0-h3) < length(h1-h2) 
                         ? line(h0,h3) : line(h1,h2), 
                      d ));
#else
       h0 = .5 - fract(p) + T(p).xy;
       for( int k; k < 9; k += k==3?2:1 ) {
           D = vec2(k%3,k/3)-1.;
           if ( ( int(T(p).z)&(1<<k) ) > 0 )
               d = min(d,  line( h0, .5 + D - fract(p) + T( p + D ).xy ) );
           else if (D.x*D.y!=0.)
               h1 = vec2(D.x,0), h2 = vec2(0,D.y),
               d = min(d,  line( .5 + h1 - fract(p) + T( p + h1 ).xy , 
                                 .5 + h2 - fract(p) + T( p + h2 ).xy ) );
        }
#endif

    O = max( 1. - d * R.yyyy/scale, 0. );       // draw segment

    d = 9.;                                     // --- draw bounty
    for( int k; k < 9; k ++ ) {
        vec2 P = floor(p)+vec2(k%3,k/3) - 1.;
        if ( T(P).w < 0. ) d = min( d, length(.5+P-p+T(P).xy));
     }
     O.r += max(8.- d*R.y/scale, 0.); 

    d = 9.;                                     // --- draw snake tail
    if ( T(p).w > 0. )  
        for( int k; k < 9; k += k==3?2:1 ) {
            if ( ( int(T(p).z)&(1<<k) ) < 1 ) continue;  // loop on connections from cell node
            vec2 P1 = floor(p) + vec2(k%3,k/3) - 1.;
            if( T(P1).w > 0. && abs(T(P1)-T(p)).w == 1.) 
                d = min(d, line( .5-fract(p) + T(p).xy,  .5+P1-p  + T(P1).xy ));
        }
    vec2 P1= floor(p) + vec2(1,0), P2, K=vec2(0,1); // test for connections between 4-neighbors
    for( int k; k++ < 4; K = vec2(-K.y,K) ) {
         P2 = floor(p) + K;
         if ( T(P1).w > 0. &&  T(P2).w > 0. && abs(T(P2)-T(P1)).w == 1. ) 
             d = min(d, line( .5+P1-p  + T(P1).xy,  .5+P2-p  + T(P2).xy ));
         P1 = P2;
         }
    O.g +=  max(0., .3 -d)*R.y/scale;

    O = sqrt(O);
 // O = T(p*2.);                             // debug
 // p = floor(p); O.b += mod(p.x+p.y,2.);    // debug: show tiling
}

#define key(a)        ( texelFetch(iChannel3,ivec2(a,1),0).x > 0.)  // LEFT:37  UP:38  RIGHT:39  DOWN:40 
#define P(u)          sin( 6.3* H(u) ) / 4.                     // random point in cell
#define S             floor(scale*R/R.y)                        // arena size
float da = 2.;

void mainImage( out vec4 O, vec2 u )
{   
    u -= .5;
    O = T(u);

    if ( iFrame < 1 && u.y < 200. )  {                          // --- init terrain                    
            vec2 P0 = O.xy = P(u), s = vec2(0,1), D;            // random point in cell
            int km = 2+8+32+128;                                // get valid connections. 4 grid dirs ok
         /**/ km=0;
            for( int k=1; k < 9; k+=2 ) {                       // trim long horiz/vertic
                D = vec2(k%3,k/3)-1.;
                if ( length( D + P(u+D) - P0 ) < 1.3) // ok if horiz/vertic short
                    km += 1 << k%3 + k/3*3;        
            }/**/
            for( int k; k < 4; k++ ) {                          // test for the diag directions
               D = vec2(k%2*2,k/2*2)-1.;
               if ( length( D + P(u+D) - P0 ) < length( D*s + P(u+D*s) - D*s.yx - P(u+D*s.yx)) ) // ok if diag shorter than antidiag
                   km += 1 << k%2*2 + k/2*2*3; 
             }
            O.z = float(km);                                    // connections flag
            if (u == floor( S * H(vec2(iTime+7.)) ) ) O.w = -1.;// bounty
        }

    if ( iFrame < 1 || T(SNK).w <  1. ) {                       // --- init
        if  ( T(SNK).w < 0. ) {                                 // wait 2" after loosing
            if ( u == vec2(SNK) )  O.w += 1.;
            return;
        }
        if ( u == vec2(SNK) )                                   // init snake pos, dir angle, tail length
             O = vec4(5,5,1.*.785,10);
        //if ( u == new() ) O.x = -1.;                            // set a pills
        return;
    }
    float c;                                                    // --- key events management
    if ( u == vec2(EV) ) c = key(37) ? 1. : key(39) ? 0. : -1., // push events key events during pause
                         O.z > slow && O.y > 0. ? O.y-- : c,    // once accounted, eat event
                         c >= 0. ? O.y++, O.x = float(int(c + 2.*O.x) & 0xfff) :c, // 0.x bits = FIFO, 0.y = next slot
                         O.z += iTimeDelta;                     // to control the pause time

    if ( iFrame > 1 && T(EV).z <= slow ) return;                // slow pace
  //if (T(EV).z <= slow *( T(EV).w!=T(SNK).z  && T(T(SNK).xy).x < 0. ?4. :1. ) ) return;// slow pace (more in turns and eats)

    if ( u == vec2(SNK) ) {                                     // --- snake head control
            vec2 d = cos( da*.785*O.z + vec2(0,11) ), D,        // direction vector
                 U = O.xy,                                      // cell Id
                 P0 =  T( U ).xy;                               // random point in cell
            float m=-1., l; int km;
            for( int k; k < 9; k += k==3?2:1 ) {
            if ( ( int(T(U).z)&(1<<k) ) < 1 ) continue;         // loop on connections
                D = vec2(k%3,k/3) - 1.;
                l = dot( normalize( D + T(U+D).xy - P0 ), d );
                if ( l > m ) m = l, km = k;                     // chose connection best align with dir
            }
            O.xy += vec2(km%3,km/3) - 1.;                       // step the connection
            O.xy = mod(O.xy, S );                               // domain wrapping
         // D = vec2(km%3,km/3) - 1.; D += T(U+D).xy - P0; O.z = atan(D.y,D.x)/da/.785; // variant: segment= new dir

            c = T(EV).y; if (c > 0.) c = ((int(T(EV))>>int(c-1.))&1) > 0 ? 1. : -1.; // c = pop bufferized action
            O.z += c; // keyDown(37) - keyDown(39);            // direction

            if (T(U).w < 0. ) O.w++;                            // eat bounty: tail +1
        //  if ( T(U).x > 0. ) O.w = -120.;                     // cross itself: loose !
        }
    if ( u == vec2(EV) )   O.z = 0.;

    if ( u.y < 200. ) {                                         // --- terrain (runtime)
            if ( T(T(SNK).xy).w < 0. && u == floor( S * H(vec2(iTime+7.)) ) ) O.w = -1.;// bounty
            if( length(u - T(SNK).xy) < .1 ) O.w = T(SNK).w;    // set cell under snake head
            if (O.w > 0.) O.w--;                                // fade snake tail
        }
}
